<template><section v-loading="loading"><el-alert v-if="error" title="资料加载失败，请刷新" type="error" :closable="false"/><el-form label-position="top" :disabled="!canEdit||saving"><div class="zj-grid"><el-form-item label="附带资料（选择已完成统一水印的PDF）"><el-select v-model="form.materialId" remote filterable clearable :remote-method="findMaterials" @visible-change="v=>v&&findMaterials('')"><el-option v-for="m in materials" :key="m.id" :value="m.id" :label="m.name"/></el-select><el-link v-if="bound.materialFile" :href="fileUrl(bound.materialFile)" target="_blank" type="primary">预览 / 打印已关联资料</el-link></el-form-item><el-form-item label="维保卡"><el-select v-model="form.cardId" remote filterable clearable :remote-method="findCards" @visible-change="v=>v&&findCards('')"><el-option v-for="c in cards" :key="c.id" :value="c.id" :label="c.code+' · '+c.name"/></el-select><el-link v-for="f in (bound.cardFile||'').split(',').filter(Boolean)" :key="f" :href="fileUrl(f)" target="_blank" type="primary">预览 / 打印已关联维保卡</el-link></el-form-item></div><el-button v-if="canEdit" type="primary" :loading="saving" @click="save">保存关联</el-button><el-button v-if="canGenerate" @click="startGenerate">在此生成维保卡</el-button></el-form><p class="zj-sub">每个维护保养项目可关联一份成品资料与一张维保卡。生成后自动关联当前项目。</p><el-dialog v-model="open" title="为当前项目生成维保卡" width="min(760px,96vw)" :before-close="close" :close-on-click-modal="false"><el-form label-position="top" :disabled="generating"><el-form-item label="项目名称"><el-input :model-value="project.projectName" disabled/></el-form-item><el-form-item label="编号（留空按最新编号自增）"><el-input v-model="card.no" :placeholder="suggestion" maxlength="100"/></el-form-item><el-form-item label="维保机构"><el-input v-model="card.company" maxlength="255"/></el-form-item><el-form-item label="选择联系人"><el-select v-model="contactId" filterable remote :remote-method="findContacts" @visible-change="v=>v&&findContacts('')" @change="choose"><el-option v-for="c in contacts" :key="c.id" :value="c.id" :label="c.name+' · '+c.phone"/></el-select></el-form-item><div class="zj-grid"><el-form-item label="负责人"><el-input v-model="card.leader" maxlength="100"/></el-form-item><el-form-item label="联系电话"><el-input v-model="card.phone" maxlength="255"/></el-form-item><el-form-item label="开始日期"><el-date-picker v-model="card.start" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="结束日期"><el-date-picker v-model="card.end" value-format="YYYY-MM-DD"/></el-form-item></div><el-form-item label="维护保养内容"><el-input v-model="card.system1" type="textarea" :rows="4" maxlength="4000"/></el-form-item></el-form><template #footer><el-button @click="close(()=>open=false)">取消</el-button><el-button :loading="previewing" :disabled="generating" @click="preview">预览</el-button><el-button type="primary" :loading="generating" :disabled="previewing" @click="generate">生成并关联</el-button></template></el-dialog><PdfPreview v-model="previewOpen" :url="previewUrl" title="维保卡排版预览"/></section></template>
<script setup>
import {projectMaterial,saveProjectMaterial,projectResourceOptions,nextCardNumber} from '@/api/projectFinance';import {generateCard,previewCard,resourceList} from '@/api/wbcardWorkspace';import {fileUrl} from '@/utils/files';import auth from '@/plugins/auth';import PdfPreview from '@/views/zhongji/wbcard/components/PdfPreview.vue';import {onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router';
const props=defineProps({project:Object,canEdit:Boolean});const {proxy}=getCurrentInstance(),form=ref({}),bound=ref({}),materials=ref([]),cards=ref([]),contacts=ref([]),contactId=ref(),loading=ref(false),error=ref(false),saving=ref(false),open=ref(false),card=ref({}),generating=ref(false),previewing=ref(false),previewOpen=ref(false),previewUrl=ref(''),suggestion=ref('');let snapshot='',cardSnapshot='',blob='';const canGenerate=computed(()=>props.canEdit&&auth.hasPermi('management:wbcard:add'));
async function load(){loading.value=true;error.value=false;try{bound.value=(await projectMaterial(props.project.id)).data;form.value={materialId:bound.value.materialId??null,cardId:bound.value.cardId??null,version:bound.value.version};materials.value=bound.value.materialId?[{id:bound.value.materialId,name:bound.value.materialName}]:[];cards.value=bound.value.cardId?[{id:bound.value.cardId,name:bound.value.cardName,code:bound.value.cardCode}]:[];snapshot=JSON.stringify(form.value)}catch{error.value=true}finally{loading.value=false}}
async function findMaterials(name){materials.value=(await projectResourceOptions(props.project.id,'material',name)).data}async function findCards(name){cards.value=(await projectResourceOptions(props.project.id,'card',name)).data}async function save(){if(saving.value)return;saving.value=true;try{await saveProjectMaterial(props.project.id,{...form.value});await load();proxy.$modal.msgSuccess('关联已保存')}finally{saving.value=false}}
async function startGenerate(){if(snapshot!==JSON.stringify(form.value)){proxy.$modal.msgWarning('请先保存当前资料关联');return}suggestion.value=(await nextCardNumber()).data.code;card.value={no:'',name:props.project.projectName,company:'河南众基消防技术有限公司',leader:props.project.leaderName||'',phone:props.project.contactPhone||'',start:props.project.startDate||'',end:props.project.endDate||'',system1:''};cardSnapshot=JSON.stringify(card.value);open.value=true}
async function findContacts(name){contacts.value=(await resourceList('contacts',{name,pageNum:1,pageSize:20})).rows}function choose(id){const c=contacts.value.find(c=>c.id===id);if(c){card.value.leader=c.name;card.value.phone=c.phone}}
function payload(){if(!card.value.leader||!card.value.phone||!card.value.start||!card.value.end||!card.value.system1)throw new Error('请填写负责人、电话、日期和维护内容');if(card.value.end<card.value.start)throw new Error('结束日期不能早于开始日期');return {...card.value,projectId:props.project.id,materialVersion:form.value.version,time:card.value.start+' 至 '+card.value.end}}
async function preview(){previewing.value=true;try{const data=payload();data.no=data.no||suggestion.value;const pdf=await previewCard(data);if(pdf.type.includes('json'))throw new Error(JSON.parse(await pdf.text()).msg);if(blob)URL.revokeObjectURL(blob);blob=URL.createObjectURL(pdf);previewUrl.value=blob;previewOpen.value=true}catch(e){proxy.$modal.msgError(e.message||'预览失败')}finally{previewing.value=false}}
async function generate(){if(generating.value)return;generating.value=true;try{const r=await generateCard(payload());open.value=false;await load();proxy.$modal.msgSuccess('已生成并关联，编号：'+r.data.code)}catch(e){if(e.message)proxy.$modal.msgError(e.message)}finally{generating.value=false}}
async function close(done){if(generating.value||previewing.value)return false;if(cardSnapshot!==JSON.stringify(card.value)){try{await proxy.$modal.confirm('放弃未保存的生成内容？')}catch{return false}}done();return true}
async function beforeLeave(){if(open.value&&!await close(()=>{}))return false;if(snapshot!==JSON.stringify(form.value)){try{await proxy.$modal.confirm('放弃未保存的资料关联？')}catch{return false}}return true}onBeforeRouteLeave(beforeLeave);onBeforeRouteUpdate(beforeLeave);watch(()=>props.project.id,()=>{open.value=false;load()});onBeforeUnmount(()=>{if(blob)URL.revokeObjectURL(blob)});onMounted(load);
</script>
